import React from 'react';

function PiePagina() {
  return (
    <footer className="footer">
      <p>
        &copy; 2026 Huellitas de Amor - Refugio de Adopción de Mascotas
        en Salta. Todos los derechos reservados.
      </p>

      <p className="aviso-demostrativo">
        Plataforma demostrativa con fines educativos. Las mascotas,
        fotografías y datos de contacto publicados son ilustrativos
        y no representan ofertas reales de adopción ni información
        oficial de organizaciones protectoras. Para realizar adopciones,
        se recomienda contactar con entidades locales verificadas.
      </p>
    </footer>
  );
}

export default PiePagina;
